def solve(tables):
    emp = tables["employees"]
    managers = emp[["emp_id", "name"]].rename(
        columns={"emp_id": "manager_id", "name": "manager_name"}
    )
    result = emp.merge(managers, on="manager_id", how="inner")
    return result[["name", "manager_name"]]
```

